mapper.select:
select t1.*, ifnull(t2.nick_name, t2.username) as send_user_name, ifnull(t3.nick_name, t3.username) as receive_user_name, t4.book_name from user_message t1 left join user t2 on t1.send_user_id = t2.id left join user t3 on t1.user_id = t3.id left join book t4 on t1.book_id = t4.id
and t1.user_id = #{userId}
and t1.msg_type = #{msgType}
and t1.read_flag = #{readFlag}
order by t1.create_time desc
